scriptc_nested.diagnostic_driver:
const fs=require('node:fs'),crypto=require('node:crypto');
const {WASI}=require('node:wasi');
const wasm=process.argv[2];
const bytes=fs.readFileSync(wasm);
const hash=crypto.createHash('sha256').update(bytes).digest('hex');
if(hash!=='c4fa7d48b379110fba0f3c920d201ea41d85c82e834f1bd9ffb52c439f2761b0')throw new Error('Different diagnostic artifact');
const wasi=new WASI({version:'preview1',args:['nested-result'],env:{},preopens:{},returnOnExit:true});
const moduleValue=new WebAssembly.Module(bytes);
const instance=new WebAssembly.Instance(moduleValue,{wasi_snapshot_preview1:wasi.wasiImport});
console.log(JSON.stringify({diagnostic_only:true,engine:process.versions,wasm_sha256:hash,guest_exit_code:wasi.start(instance)}));
